import{_ as e,o as a,c as r,a2 as n}from"./chunks/framework.DGu13UIe.js";const p=JSON.parse('{"title":"第 13 课 · 推理服务框架一览（扩展阅读）","description":"","frontmatter":{"editLink":"https://github.com/SyncLionPaw/bagent/edit/main/lessons/13-inference-engines/doc.md"},"headers":[],"relativePath":"chapters/13-inference-engines.md","filePath":"chapters/13-inference-engines.md"}'),o={name:"chapters/13-inference-engines.md"};function l(s,t,i,g,h,d){return a(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="第-13-课-·-推理服务框架一览-扩展阅读" tabindex="-1">第 13 课 · 推理服务框架一览（扩展阅读） <a class="header-anchor" href="#第-13-课-·-推理服务框架一览-扩展阅读" aria-label="Permalink to &quot;第 13 课 · 推理服务框架一览（扩展阅读）&quot;">​</a></h1><p><strong>约 15 分钟</strong> · 纯阅读，<strong>无代码</strong> · 第 12 课之后</p><h2 id="你为什么需要知道这些" tabindex="-1">你为什么需要知道这些 <a class="header-anchor" href="#你为什么需要知道这些" aria-label="Permalink to &quot;你为什么需要知道这些&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>你在做什么</th></tr></thead><tbody><tr><td>第 11 课</td><td>调云端 <strong><code>/chat/completions</code></strong>，收 JSON</td></tr><tr><td>第 12 课</td><td>用 <strong><code>transformers</code></strong> 在本机 <code>generate</code>，一次一个请求、自己计时</td></tr><tr><td>线上产品</td><td>同一套权重，但要 <strong>高吞吐、低延迟、连续批处理、OpenAI 兼容 API</strong></td></tr></tbody></table><p>第 12 课的 <code>model.generate</code> 适合<strong>学习和体感</strong>；<br> 真要对外提供「像 DeepSeek 那样的推理服务」，通常不会在业务进程里直接挂一个 Hugging Face <code>pipeline</code>，而是把权重交给 <strong>推理引擎 / 推理服务框架</strong>，前面再挂 API 网关（第 11 课那张图里的中间层）。</p><p>本课只做<strong>地图</strong>：名字、解决什么问题、官方文档链接。想深入时按链接自己读，不必在本仓库写代码。</p><hr><h2 id="一张对照表-先建立印象" tabindex="-1">一张对照表（先建立印象） <a class="header-anchor" href="#一张对照表-先建立印象" aria-label="Permalink to &quot;一张对照表（先建立印象）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>大致定位</th><th>和本课路线的关系</th></tr></thead><tbody><tr><td><strong><a href="https://docs.vllm.ai/" target="_blank" rel="noreferrer">vLLM</a></strong></td><td>开源 GPU 推理与服务，PagedAttention、continuous batching，常提供 OpenAI 兼容 HTTP</td><td>自建推理服务时最常见选项之一</td></tr><tr><td><strong><a href="https://docs.sglang.ai/" target="_blank" rel="noreferrer">SGLang</a></strong></td><td>高性能推理 + 结构化生成 / 前端语言，强调吞吐与灵活控制流</td><td>与 vLLM 同属「专业推理栈」，选型时可对比阅读</td></tr><tr><td><strong><a href="https://github.com/ggml-org/llama.cpp" target="_blank" rel="noreferrer">llama.cpp</a></strong></td><td>C/C++，CPU/Apple Silicon/部分 GPU，量化友好，偏本地与边缘</td><td>本机轻量跑模型、少依赖 Python 时</td></tr><tr><td><strong><a href="https://nvidia.github.io/TensorRT-LLM/" target="_blank" rel="noreferrer">TensorRT-LLM</a></strong></td><td>NVIDIA 栈上的优化推理与部署</td><td>深度用 NVIDIA GPU 做生产部署时</td></tr><tr><td><strong><a href="https://huggingface.co/docs/text-generation-inference" target="_blank" rel="noreferrer">Text Generation Inference (TGI)</a></strong></td><td>Hugging Face 推出的推理服务容器</td><td>HF 生态、K8s 部署</td></tr><tr><td><strong><a href="https://github.com/ollama/ollama" target="_blank" rel="noreferrer">Ollama</a></strong></td><td>本地一键拉模型 + 聊天 API，易用</td><td>快速体验本地模型，不是最大吞吐方案</td></tr></tbody></table><p>它们都在做一件事：<strong>把 checkpoint 变成可持续对外服务的推理能力</strong>——只是优化方向（吞吐 / 延迟 / 易用 / 硬件）不同。</p><hr><h2 id="vllm" tabindex="-1">vLLM <a class="header-anchor" href="#vllm" aria-label="Permalink to &quot;vLLM&quot;">​</a></h2><p><strong>解决什么</strong>：同一张 GPU 上同时服务很多请求，提高 <strong>tokens/s</strong>，降低排队；用 <strong>PagedAttention</strong> 等方式更省显存。</p><p><strong>你会在什么场景听到它</strong>：自建 API 替代直接调云端、K8s 里起 <code>vllm serve</code>、与 LangChain / 自研 Agent 网关对接。</p><p><strong>建议阅读（官方）</strong>：</p><ul><li>文档首页：<a href="https://docs.vllm.ai/" target="_blank" rel="noreferrer">https://docs.vllm.ai/</a></li><li>快速开始：<a href="https://docs.vllm.ai/en/latest/getting_started/quickstart.html" target="_blank" rel="noreferrer">Getting Started</a></li><li>OpenAI 兼容服务：<a href="https://docs.vllm.ai/en/latest/serving/openai_compatible_server.html" target="_blank" rel="noreferrer">OpenAI Compatible Server</a></li><li>设计背景 PagedAttention 论文（可选）：<a href="https://arxiv.org/abs/2309.06180" target="_blank" rel="noreferrer">Efficient Memory Management for LLM Serving (PagedAttention)</a></li></ul><p>读完后应能回答：<strong>它和第 12 课脚本比，多出来的主要是批处理与显存管理，而不是「另一种模型」</strong>。</p><hr><h2 id="sglang" tabindex="-1">SGLang <a class="header-anchor" href="#sglang" aria-label="Permalink to &quot;SGLang&quot;">​</a></h2><p><strong>解决什么</strong>：高性能 <strong>LLM 推理运行时</strong>，同时提供 <strong>SGL 前端语言</strong>，方便写带分支、并行、工具流的生成程序（和纯字符串 prompt 略有不同）。</p><p><strong>你会在什么场景听到它</strong>：与 vLLM 并列讨论选型；需要复杂控制流或极致吞吐时的方案之一。</p><p><strong>建议阅读（官方）</strong>：</p><ul><li>文档首页：<a href="https://docs.sglang.ai/" target="_blank" rel="noreferrer">https://docs.sglang.ai/</a></li><li>安装与本地跑起来：<a href="https://docs.sglang.ai/start/install.html" target="_blank" rel="noreferrer">Install &amp; Local Run</a></li><li>后端与 OpenAI 兼容：<a href="https://docs.sglang.ai/backend/openai_api_completions.html" target="_blank" rel="noreferrer">Backend &amp; API</a>（以文档站当前目录为准）</li></ul><p>和 vLLM 不必二选一才能学完本课程——<strong>知道「还有这一条技术线」即可</strong>；真要部署时再按团队硬件与 API 需求选型。</p><hr><h2 id="其它常见名字-按需点开" tabindex="-1">其它常见名字（按需点开） <a class="header-anchor" href="#其它常见名字-按需点开" aria-label="Permalink to &quot;其它常见名字（按需点开）&quot;">​</a></h2><h3 id="llama-cpp" tabindex="-1">llama.cpp <a class="header-anchor" href="#llama-cpp" aria-label="Permalink to &quot;llama.cpp&quot;">​</a></h3><ul><li>仓库：<a href="https://github.com/ggml-org/llama.cpp" target="_blank" rel="noreferrer">https://github.com/ggml-org/llama.cpp</a></li><li>特点：量化模型（GGUF）、CPU/Metal 友好，适合「笔记本上先跑起来」。</li><li>文档/wiki：见仓库 <strong>Documentation</strong> 与 <a href="https://github.com/ggml-org/llama.cpp/wiki" target="_blank" rel="noreferrer">wiki</a>。</li></ul><h3 id="tensorrt-llm-nvidia" tabindex="-1">TensorRT-LLM（NVIDIA） <a class="header-anchor" href="#tensorrt-llm-nvidia" aria-label="Permalink to &quot;TensorRT-LLM（NVIDIA）&quot;">​</a></h3><ul><li>文档：<a href="https://nvidia.github.io/TensorRT-LLM/" target="_blank" rel="noreferrer">https://nvidia.github.io/TensorRT-LLM/</a></li><li>特点：在 NVIDIA GPU 上做图优化与内核融合，偏<strong>生产部署与性能极限</strong>。</li></ul><h3 id="hugging-face-tgi" tabindex="-1">Hugging Face TGI <a class="header-anchor" href="#hugging-face-tgi" aria-label="Permalink to &quot;Hugging Face TGI&quot;">​</a></h3><ul><li>文档：<a href="https://huggingface.co/docs/text-generation-inference" target="_blank" rel="noreferrer">Text Generation Inference</a></li><li>特点：容器化推理服务，和 HF Hub 模型配合紧。</li></ul><h3 id="ollama" tabindex="-1">Ollama <a class="header-anchor" href="#ollama" aria-label="Permalink to &quot;Ollama&quot;">​</a></h3><ul><li>官网 / 仓库：<a href="https://ollama.com" target="_blank" rel="noreferrer">https://ollama.com</a> · <a href="https://github.com/ollama/ollama" target="_blank" rel="noreferrer">GitHub</a></li><li>特点：<strong>易用</strong>优先；本地 <code>ollama run</code> + HTTP API，适合开发机体验，底层可能组合多种运行时。</li></ul><hr><h2 id="和-deepseek-第-11-课-api-怎么接上" tabindex="-1">和 DeepSeek / 第 11 课 API 怎么接上 <a class="header-anchor" href="#和-deepseek-第-11-课-api-怎么接上" aria-label="Permalink to &quot;和 DeepSeek / 第 11 课 API 怎么接上&quot;">​</a></h2><p>很多推理框架会提供 <strong>OpenAI 兼容</strong> 的 <code>POST /v1/chat/completions</code>（路径因部署略异）。<br> 你在第 1–10 课写的 <code>fetch</code> + <code>messages</code> <strong>往往只需改 <code>baseURL</code> 和 <code>model</code></strong>，Harness 逻辑可以不变——这也是课程坚持教兼容 API 的原因。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的 Agent (JS)  →  fetch  →  vLLM / SGLang / Ollama 提供的 HTTP</span></span>
<span class="line"><span>                              →  框架内部：加载权重、批处理、KV Cache</span></span>
<span class="line"><span>                              →  返回 choices / usage（形态接近第 11 课）</span></span></code></pre></div><p>云端 DeepSeek 则是厂商帮你运维了右侧整栈；本课列的项目是<strong>你自己运维</strong>时的常见选型。</p><hr><h2 id="本课建议怎么学" tabindex="-1">本课建议怎么学 <a class="header-anchor" href="#本课建议怎么学" aria-label="Permalink to &quot;本课建议怎么学&quot;">​</a></h2><ol><li>先扫上文对照表，记住 <strong>vLLM / SGLang</strong> 两个名字。</li><li>各打开一篇 <strong>Quickstart</strong>，看启动命令与监听端口，不必跟装。</li><li>看一页 <strong>OpenAI compatible API</strong>，对照第 11 课响应字段。</li><li>有 Mac 且只想本地玩：可浏览 <strong>Ollama</strong> 或 <strong>llama.cpp</strong> 文档目录，和第 12 课对比「易用 vs 教学脚本」。</li></ol><p><strong>检查点（自测）</strong>：</p><ul><li>[ ] 能说出 vLLM / SGLang 主要优化的是 <strong>Serving</strong>，不是训练吗？</li><li>[ ] 能说出它们与第 12 课 <code>transformers</code> 脚本的分工差异吗？</li><li>[ ] 知道 Agent 代码换 <code>baseURL</code> 可能就能对接自建推理服务吗？</li></ul><hr><h2 id="下一课" tabindex="-1">下一课 <a class="header-anchor" href="#下一课" aria-label="Permalink to &quot;下一课&quot;">​</a></h2><p>第二部分连载继续（token、上下文、RAG 等可按目录更新）。<br><a href="/bagent/chapters/14-fastapi-stream.html">第 14 课</a> → <a href="/bagent/chapters/15-sse-parse.html">第 15 课 解析</a> → <a href="/bagent/chapters/18-streaming.html">第 18 课 浏览器打字机</a>。</p><p><a href="/bagent/chapters/12-local-inference.html">← 第 12 课</a></p>`,48)])])}const m=e(o,[["render",l]]);export{p as __pageData,m as default};
